        return (float4(v,0.,1.)*amzLayerToScreen()).xy;
    }
      float2x2 rot = float2x2(cos(2.3999632), sin(2.3999632), -sin(2.3999632), cos(2.3999632));
      float3 Bokeh(int tex, float2 uv, float radius)
      {
          float3 acc = float3(0), div = acc;
          float r = RADIUS;
          float2 vangle = float2(0.0,radius*.01 / sqrt(float(ITERATIONS)));
       for (int __amk = 0; __amk < 408; ++__amk) {
    float j = float((0.0) + (1) * float(__amk));
    if (!(j < ITERATIONS)) break;

              r += 1. / r;
           vangle = rot * vangle;
              float3 col = amzTexture(tex, uv + (r-1.) * vangle).xyz;
        float3 bokeh = pow(col, float3(4));
        acc += col * bokeh;
        div += bokeh;

}
       return acc / div;
      }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 satriyaid;
        satriyaid = amzScreenNorm();
     float4 fragColor;
          float2 uv = satriyaid;
       float rad = .8 - .8*((progressa+0.15) * 6.283);
          if (0.0 >= 1.0)
          {
           rad = (0.0/screen.zw.x)*3.0;
          }
           fragColor = float4(Bokeh(0, uv, rad), 1.0);
     float4 factor = mix(texColorX,fragColor,alpha);
        float4 resultfinal;
        if( int(blendMode)==0 ) {
            resultfinal = (factor * bright) * texColor.a;
        } else if( int(blendMode)==1 ) {
            factor *= bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(blendMode)==2 ) {
            factor *= bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = resultfinal;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
